-- V37: 业务类型字典（项目性质/项目类型/业务类型/字号/收费频度/税收分类/发票品名）
-- 数据来源：业务配置导出表，去重后共 84 行
CREATE TABLE IF NOT EXISTS business_type (
    id            BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    -- 项目性质：收入型 / 无收入型
    biz_nature    VARCHAR(20)  NOT NULL,
    -- 项目类型
    project_type  VARCHAR(50)  NOT NULL,
    -- 业务类型（同项目类型下唯一）
    biz_type      VARCHAR(100) NOT NULL,
    biz_desc      VARCHAR(500),
    -- 字号类型：审/验/咨/代/商（空表示不参与开票编号）
    no_char       VARCHAR(10),
    -- 收费频度：次/月度/季度
    fee_freq      VARCHAR(20),
    tax_code      VARCHAR(30),
    tax_class     VARCHAR(100),
    invoice_item  VARCHAR(100),
    sort          INT,
    create_by     VARCHAR(50),
    create_time   TIMESTAMP,
    update_by     VARCHAR(50),
    update_time   TIMESTAMP,
    CONSTRAINT uk_business_type UNIQUE (project_type, biz_type)
);






-- 项目表新增项目性质/业务类型，历史类型值归并到字典口径
ALTER TABLE project ADD COLUMN biz_nature VARCHAR(20);
ALTER TABLE project ADD COLUMN biz_type VARCHAR(100);
UPDATE project SET type = '财务报表审计' WHERE type IN ('审计', 'Audit', 'audit');
UPDATE project SET type = '验资业务' WHERE type = '验资';
UPDATE project SET type = '涉税服务' WHERE type IN ('税务', '税务咨询', '咨询');
UPDATE project SET type = '财税咨询' WHERE type = '代理记账';
UPDATE project SET biz_nature = '收入型' WHERE type IN ('财务报表审计', '验资业务', '涉税服务', '财税咨询', '专项审计业务', '审阅', '商定程序业务', '商务行政', '其他咨询', 'Instruction');

-- 合同表新增业务类型（字号按其字号类型解析）
ALTER TABLE contract ADD COLUMN biz_type VARCHAR(100);

-- 发票表新增开票要素（按业务类型自动带出）
ALTER TABLE invoice ADD COLUMN invoice_item VARCHAR(100);
ALTER TABLE invoice ADD COLUMN tax_code VARCHAR(30);
ALTER TABLE invoice ADD COLUMN tax_class VARCHAR(100);
